CREATE OR REPLACE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `Product Sales for 1997` AS select `Categories`.`CategoryName` AS `CategoryName`,`Products`.`ProductName` AS `ProductName`,sum(round(`Order Details`.`UnitPrice` * `Order Details`.`Quantity` * (1 - `Order Details`.`Discount`),2)) AS `ProductSales` from ((`Categories` join `Products` on(`Categories`.`CategoryID` = `Products`.`CategoryID`)) join (`Orders` join `Order Details` on(`Orders`.`OrderID` = `Order Details`.`OrderID`)) on(`Products`.`ProductID` = `Order Details`.`ProductID`)) where `Orders`.`ShippedDate` between '1997-01-01' and '1997-12-31' group by `Categories`.`CategoryName`,`Products`.`ProductName`;
